+    // flutter_agent_harness quality.yml shape).
+    var UNRESOLVED_MATRIX_JOB = 'Core tests (shard ${{ matrix.shard }}/4)';
+    var JOBS_PAYLOAD = { jobs: [
+        { id: 1, name: UNRESOLVED_MATRIX_JOB, status: 'queued', conclusion: null,
