        io.write = function () {
            var err = (writeResults && writeResults.length > io.writes) ? writeResults[io.writes] : null;
            io.writes++;
            if (err) throw err;
            return true;
        };
        io.exec = function () {
            var err = (execResults && execResults.length > io.execs) ? execResults[io.execs] : null;
            io.execs++;
            if (err) throw err;
